sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Add your code here
    // --------------------------------------------------
    // Debugging practice script for Script Debugger
    // --------------------------------------------------

    // Short description を強制的に設定
    current.short_description = "This text set by the Debugging Business Rules business rule.";

    // state の値を変数に格納
    var myNum = current.state;

    // try / catch 内の未定義関数（例外は捕捉される）
    try {
        thisFunctionDoesNotExist();
    }
    catch (err) {
        gs.error("NeedIt App: a JavaScript runtime error occurred - " + err);
    }

    // try / catch 外の未定義関数（ランタイムエラー）
    thisFunctionAlsoDoesNotExist();

    // --- JavaScript Closure のデモ ---
var x = 7;

    function numFunc() {
        var x = 10;
        return {
            getNum: function () {
                return x;
            },
            setNum: function (newNum) {
                x = newNum;
            }
        };
    }

    var callFunc = numFunc();
    callFunc.getNum();   // 10
    callFunc.setNum(2);  // x = 2
    callFunc.getNum();   // 2

})(current, previous);
